'use strict';
const fs=require('fs');const path=require('path');const crypto=require('crypto');
const contract=require('../V14_ACCEPTANCE_EVIDENCE_BUNDLE_CONTRACT_V1.7.83.json');
const runner=require('./v14SegmentedAcceptanceRunner');
const receiptAutomation=require('./v14ReleaseReceiptAutomation');
const ROOT=path.join(__dirname,'..');
function sha(bytes){return crypto.createHash('sha256').update(bytes).digest('hex');}
function readJson(root,name){return JSON.parse(fs.readFileSync(path.join(root,name),'utf8'));}
function read(root,name){return fs.readFileSync(path.join(root,name));}
function stable(value){if(Array.isArray(value))return value.map(stable);if(value&&typeof value==='object'){const out={};for(const key of Object.keys(value).sort())out[key]=stable(value[key]);return out;}return value;}
function parseInventory(bytes){const records=[];const errors=[];for(const [index,line] of bytes.toString('utf8').split(/\n/).entries()){if(!line)continue;const m=line.match(/^([a-f0-9]{64})  (.+)$/);if(!m){errors.push(`line:${index+1}`);continue;}records.push({sha256:m[1],path:m[2]});}return{records,errors};}
function evaluate(root=ROOT){const errors=[];for(const name of contract.required_files)if(!fs.existsSync(path.join(root,name)))errors.push(`missing:${name}`);if(errors.length)return{ok:false,errors,deploymentAuthorized:false,launchState:'NO_GO'};
 const pkg=readJson(root,'package.json'),manifest=readJson(root,'ACCEPTANCE_SUITE_MANIFEST_V1.7.83.json'),working=readJson(root,'WORKING_TREE_ACCEPTANCE_V1.7.83.json'),truth=readJson(root,'CURRENT_RELEASE_TRUTH_V1.7.83.json'),binding=readJson(root,'ARTIFACT_BINDING_AND_MODE_RECEIPT.json');
 const manifestValidation=runner.validateManifest(manifest,pkg);errors.push(...manifestValidation.errors.map(x=>`manifest:${x}`));
 if(pkg.version!==contract.release_version||manifest.release_version!==contract.release_version||working.releaseVersion!==contract.release_version||truth.releaseVersion!==contract.release_version)errors.push('release-version');
 if(binding.selected_authoritative_base?.sha256!==contract.source_artifact.sha256||binding.selected_authoritative_base?.version!==contract.source_version||truth.selectedBase?.sha256!==contract.source_artifact.sha256)errors.push('source-identity');
 if(binding.governing_packet?.sha256!==contract.governing_packet.sha256||truth.currentPromptPack?.packetSha256!==contract.governing_packet.sha256)errors.push('packet-identity');
 if(manifest.expected_command_count!==contract.expected_dependency_independent_commands||working.commandsPerRun!==contract.expected_dependency_independent_commands||truth.sourcePackage?.dependencyIndependentParts!==contract.expected_dependency_independent_commands)errors.push('command-count');
 if(working.runs<2||working.identicalOutput!==true||working.state!=='FINALIZED_WORKING_TREE_ACCEPTED'||!/^[a-f0-9]{64}$/.test(String(working.testLogSha256||'')))errors.push('working-acceptance');
 const chain=runner.splitTestChain(pkg.scripts?.test);const uniqueIds=new Set(manifest.commands.map(x=>x.id));const uniqueCommands=new Set(manifest.commands.map(x=>x.command));if(chain.length!==manifest.commands.length||uniqueIds.size!==manifest.commands.length||uniqueCommands.size!==manifest.commands.length)errors.push('command-uniqueness');
 for(const test of contract.required_current_tests)if(!chain.includes(`node ${test}`))errors.push(`missing-current-test:${test}`);
 const packageJson=read(root,'package.json'),packageLock=read(root,'package-lock.json'),sbom=read(root,'SBOM.spdx.json');const hashes={package_json_sha256:sha(packageJson),package_lock_sha256:sha(packageLock),sbom_sha256:sha(sbom)};
 if(working.sourceHashes?.packageJsonSha256!==hashes.package_json_sha256||working.sourceHashes?.packageLockSha256!==hashes.package_lock_sha256||working.sourceHashes?.sbomSha256!==hashes.sbom_sha256)errors.push('working-source-hashes');
 const payloadBytes=read(root,'RELEASE_PAYLOAD_INVENTORY_SHA256.txt'),legacyBytes=read(root,'FILE_INVENTORY_SHA256.txt');const payload=parseInventory(payloadBytes),legacy=parseInventory(legacyBytes);errors.push(...payload.errors.map(x=>`payload:${x}`),...legacy.errors.map(x=>`legacy:${x}`));
 const receiptValidation=receiptAutomation.validate(root);errors.push(...receiptValidation.errors.map(x=>`receipt:${x}`));
 const ownerText=read(root,'OWNER_RECEIPT.txt').toString('utf8');if(!ownerText.includes(`PRODUCT_VERSION: ${contract.release_version}`)||!ownerText.includes(`STARTING_ARTIFACT_SHA256: ${contract.source_artifact.sha256}`))errors.push('owner-identity');if(/FINAL_DELIVERY_ZIP_(SHA256|SIZE_BYTES)\s*:/i.test(ownerText))errors.push('owner-self-reference');
 if(truth.finalArchive?.sha256!==null||truth.finalArchive?.sizeBytes!==null||truth.finalArchive?.identityState!=='REPORTED_AFTER_IMMUTABLE_PACKAGING')errors.push('detached-final-boundary');if(truth.deploymentAuthorized!==false||truth.launchState!=='NO_GO')errors.push('closed-gates');
 const bundle={schema_id:'SJP-V14-ACCEPTANCE-EVIDENCE-BUNDLE-2026-08-03-V1',release_version:contract.release_version,source_artifact:contract.source_artifact,governing_packet:contract.governing_packet,manifest_sha256:manifestValidation.manifestSha256,expected_command_count:manifest.expected_command_count,working_test_log_sha256:working.testLogSha256,working_runs:working.runs,all_working_runs_identical:working.identicalOutput,package_hashes:hashes,payload_inventory:{sha256:sha(payloadBytes),records:payload.records.length,validated:receiptValidation.ok},legacy_inventory:{sha256:sha(legacyBytes),records:legacy.records.length},owner_receipt_sha256:sha(Buffer.from(ownerText)),candidate_state:truth.candidateArtifact?.state||'PENDING',final_outer_zip_identity:'REPORTED_AFTER_IMMUTABLE_PACKAGING',final_outer_zip_sha256_embedded:false,final_outer_zip_size_embedded:false,postgres_acceptance_claimed:false,deployment_authorized:false,launch_state:'NO_GO'};bundle.bundle_digest=sha(Buffer.from(JSON.stringify(stable(bundle))));
 return{ok:errors.length===0,errors,bundle,deploymentAuthorized:false,launchState:'NO_GO'};}

function validateBundle(bundle){const errors=[];if(bundle?.schema_id!=='SJP-V14-ACCEPTANCE-EVIDENCE-BUNDLE-2026-08-03-V1')errors.push('schema');if(bundle?.release_version!==contract.release_version)errors.push('release-version');if(bundle?.source_artifact?.sha256!==contract.source_artifact.sha256)errors.push('source-artifact');if(bundle?.governing_packet?.sha256!==contract.governing_packet.sha256)errors.push('governing-packet');if(bundle?.expected_command_count!==contract.expected_dependency_independent_commands)errors.push('command-count');if(bundle?.final_outer_zip_sha256_embedded!==false||bundle?.final_outer_zip_size_embedded!==false||bundle?.final_outer_zip_identity!=='REPORTED_AFTER_IMMUTABLE_PACKAGING')errors.push('outer-boundary');if(bundle?.deployment_authorized!==false||bundle?.launch_state!=='NO_GO')errors.push('closed-gates');const copy=JSON.parse(JSON.stringify(bundle||{}));delete copy.bundle_digest;const expected=sha(Buffer.from(JSON.stringify(stable(copy))));if(bundle?.bundle_digest!==expected)errors.push('bundle-digest');return{ok:errors.length===0,errors,bundleDigest:bundle?.bundle_digest||null,deploymentAuthorized:false,launchState:'NO_GO'};}

function ownerView(){return{contract,result:evaluate(),persisted:false,finalOuterZipIdentityEmbedded:false,deploymentAuthorized:false,launchState:'NO_GO'};}
module.exports={sha,stable,parseInventory,evaluate,validateBundle,ownerView};
